CREATE TABLE INVENTÁRIO (Número_de_Slots INT NOT NULL, Classe_Inventário VARCHAR(50) NOT NULL, id_inventário INT NOT NULL, PRIMARY KEY (id_inventário));
CREATE TABLE EFEITO (Nome VARCHAR(50) NOT NULL, Nível INT NOT NULL, Tempo_de_Efeito INT NOT NULL, Tipo_de_efeito VARCHAR(50) NOT NULL, PRIMARY KEY (Nome, Nível), UNIQUE (Nível));
CREATE TABLE JOGADOR (Nickname VARCHAR(50) NOT NULL, Vida INT NOT NULL, Dano_Base INT NOT NULL, Fome INT NOT NULL, Experiência INT NOT NULL, Fôlego INT NOT NULL, Armadura INT NOT NULL, Hitbox INT NOT NULL, Velocidade INT, Pulo INT NOT NULL, Inventário INT NOT NULL, Efeito VARCHAR(50), Nível INT, PRIMARY KEY (Nickname), FOREIGN KEY (Inventário) REFERENCES INVENTÁRIO(id_inventário), FOREIGN KEY (Efeito, Nível) REFERENCES EFEITO(Nome, Nível));
CREATE TABLE TIPO_MOB (Nome VARCHAR(50) NOT NULL, Vida INT NOT NULL, Dano_Base INT, Fôlego INT NOT NULL, Hitbox INT NOT NULL, Velocidade INT NOT NULL, Pulo INT NOT NULL, XP_Dropável INT NOT NULL, Raio_de_detecção INT NOT NULL, Prociável BOOLEAN, Armadura INT, Item_Carregável INT, Classe_Mob VARCHAR(50) NOT NULL, PRIMARY KEY (Nome));
CREATE TABLE MUNDO (Seed INT NOT NULL, Nome VARCHAR(100) NOT NULL, Dificuldade VARCHAR(10) NOT NULL, Permitir_comandos BOOLEAN NOT NULL, Tipo VARCHAR(50) NOT NULL, Modo VARCHAR(30) NOT NULL, Gerar_baú_bônus BOOLEAN NOT NULL, Gerar_estruturas BOOLEAN NOT NULL, Experimentos BOOLEAN NOT NULL, Pacote_de_Dados VARCHAR(100) NOT NULL, Save VARCHAR(100) NOT NULL, Jogador VARCHAR(50) NOT NULL, PRIMARY KEY (Save), FOREIGN KEY (Jogador) REFERENCES JOGADOR(Nickname));
CREATE TABLE DIMENSÃO (Nome VARCHAR(50) NOT NULL, Aparência_Visual VARCHAR(50) NOT NULL, Pode_dormir BOOLEAN NOT NULL, Mundo VARCHAR(100) NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Mundo) REFERENCES MUNDO(Save));
CREATE TABLE TIPO_BIOMA (Nome VARCHAR(100) NOT NULL, Altitude_Média INT NOT NULL, Temperatura INT NOT NULL, Tipo_de_Precipitação VARCHAR(50), Cor_da_Folhagem VARCHAR(30), Cor_da_água VARCHAR(30), Dimensão VARCHAR(50) NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Dimensão) REFERENCES DIMENSÃO(Nome));
CREATE TABLE TIPO_ITEM (Nome VARCHAR(50) NOT NULL, Dano_Base INT NOT NULL, Área_de_Ataque INT NOT NULL, Repulsão INT NOT NULL, Pilha_Máxima INT NOT NULL, Raridade VARCHAR(10) NOT NULL, Efeito_Nome VARCHAR(50), Nível INT, PRIMARY KEY (Nome), FOREIGN KEY (Efeito_Nome, Nível) REFERENCES EFEITO(Nome, Nível));
CREATE TABLE SLOT_INVENTÁRIO (Número_Slot INT NOT NULL, Quantidade INT NOT NULL, Mostrar_Durabilidade_atual INT NOT NULL, Item VARCHAR(50) NOT NULL, Inventário INT NOT NULL, PRIMARY KEY (Número_Slot, Inventário), FOREIGN KEY (Item) REFERENCES TIPO_ITEM(Nome), FOREIGN KEY (Inventário) REFERENCES INVENTÁRIO(id_inventário));
CREATE TABLE TIPO_BLOCO (Nome VARCHAR(50) NOT NULL, Durabilidade INT NOT NULL, Condição_de_Quebra INT, Hitbox INT NOT NULL, Dropável BOOLEAN NOT NULL, Interagível BOOLEAN NOT NULL, Quebrável BOOLEAN NOT NULL, Coletável BOOLEAN NOT NULL, Número_Slot INT NOT NULL, Inventário INT NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Número_Slot, Inventário) REFERENCES SLOT_INVENTÁRIO(Número_Slot, Inventário));
CREATE TABLE RECEITA_CRAFTING (Tipo_de_Crafting VARCHAR(30) NOT NULL, Tempo_para_o_Crafting INT, Receita VARCHAR(50) NOT NULL, Item_Resultado VARCHAR(50), Quantidade_Resultado INT NOT NULL DEFAULT 1, PRIMARY KEY (Receita), FOREIGN KEY (Item_Resultado) REFERENCES TIPO_ITEM(Nome));
CREATE TABLE DOMESTICAÇãO_MOB (Name_Tag VARCHAR(50), Coordenadas INT NOT NULL, Data_Domesticação DATE NOT NULL, Jogador VARCHAR(50) NOT NULL, Mob VARCHAR(50) NOT NULL, PRIMARY KEY (Data_Domesticação), FOREIGN KEY (Jogador) REFERENCES JOGADOR(Nickname), FOREIGN KEY (Mob) REFERENCES TIPO_MOB(Nome));
CREATE TABLE TIPO_MOB_PACÍFICO (Nome VARCHAR(50) NOT NULL, Domesticável BOOLEAN NOT NULL, Comportamento_de_Fuga BOOLEAN NOT NULL, Montável BOOLEAN NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Nome) REFERENCES TIPO_MOB(Nome));
CREATE TABLE TIPO_MOB_HOSTIL (Sensibilidade_ao_Sol BOOLEAN NOT NULL, Spawn_no_escuro BOOLEAN NOT NULL, Barra_de_Vida_Visível BOOLEAN NOT NULL, É_Boss BOOLEAN NOT NULL, Nome VARCHAR(50) NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Nome) REFERENCES TIPO_MOB(Nome));
CREATE TABLE TIPO_MOB_NEUTRO (Nome VARCHAR(50) NOT NULL, Sofreu_Ataque BOOLEAN NOT NULL, Domesticável BOOLEAN NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Nome) REFERENCES TIPO_MOB(Nome));
CREATE TABLE TIPO_ESTRUTURA (Nome VARCHAR(50) NOT NULL, Variante VARCHAR(50) NOT NULL, Extensão INT NOT NULL, Bioma VARCHAR(50) NOT NULL, PRIMARY KEY (Nome, Variante), FOREIGN KEY (Bioma) REFERENCES TIPO_BIOMA(Nome));
CREATE TABLE ENTIDADE_DINÂMICA (Nome VARCHAR(50) NOT NULL, Quebrável BOOLEAN NOT NULL, Hitbox INT NOT NULL, Data_de_Criação DATE NOT NULL, Item VARCHAR(50) NOT NULL, PRIMARY KEY (Nome, Data_de_Criação), FOREIGN KEY (Item) REFERENCES TIPO_ITEM(Nome));
CREATE TABLE TIPO_ITEM_CONSUMÍVEL (Lançável BOOLEAN NOT NULL, Fome_recuperada INT, Nome VARCHAR(50) NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Nome) REFERENCES TIPO_ITEM(Nome));
CREATE TABLE TIPO_ITEM_DESGASTÁVEL (Nome VARCHAR(50) NOT NULL, Durabilidade INT NOT NULL, Equipável BOOLEAN NOT NULL, PRIMARY KEY (Nome), FOREIGN KEY (Nome) REFERENCES TIPO_ITEM(Nome));
CREATE TABLE INVENTÁRIO_JOGADOR (Slot_hotbar_selecionado INT NOT NULL, id_inventário INT NOT NULL, PRIMARY KEY (id_inventário), FOREIGN KEY (id_inventário) REFERENCES INVENTÁRIO(id_inventário));
CREATE TABLE INVENTÁRIO_BAÚ (Expansível BOOLEAN NOT NULL, Coordenadas_Baú INT NOT NULL, Dimensão VARCHAR(50) NOT NULL, Tipo_Baú INT NOT NULL, Nome VARCHAR(50) NOT NULL, PRIMARY KEY (Tipo_Baú), FOREIGN KEY (Tipo_Baú) REFERENCES INVENTÁRIO(id_inventário), FOREIGN KEY (Nome) REFERENCES DIMENSÃO(Nome));
CREATE TABLE ITEM_CLASSE (Classe_Item VARCHAR(50) NOT NULL, Nome VARCHAR(50) NOT NULL, PRIMARY KEY (Classe_Item, Nome), FOREIGN KEY (Nome) REFERENCES TIPO_ITEM(Nome));
CREATE TABLE CRAFTING_ITEM (Posição_Slot INT NOT NULL, Quantidade INT NOT NULL, Item VARCHAR(50) NOT NULL, Receita VARCHAR(50) NOT NULL, Combustível BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY (Posição_Slot, Item, Receita), FOREIGN KEY (Item) REFERENCES TIPO_ITEM(Nome), FOREIGN KEY (Receita) REFERENCES RECEITA_CRAFTING(Receita));
CREATE TABLE DIMENSÃO_PORTAL (Tipo_do_Portal VARCHAR(50) NOT NULL, Coordenadas INT NOT NULL, Dimensão VARCHAR(50) NOT NULL, PRIMARY KEY (Dimensão, Tipo_do_Portal, Coordenadas), FOREIGN KEY (Dimensão) REFERENCES DIMENSÃO(Nome));
CREATE TABLE GERAÇÃO_MOB_DIMENSÃO (Taxa_de_Spawn INT NOT NULL, Mob VARCHAR(50) NOT NULL, Dimensão VARCHAR(50) NOT NULL, PRIMARY KEY (Mob, Dimensão), FOREIGN KEY (Mob) REFERENCES TIPO_MOB(Nome), FOREIGN KEY (Dimensão) REFERENCES DIMENSÃO(Nome));
CREATE TABLE GERAÇãO_BLOCO_BIOMA (Taxa_de_Geração INT NOT NULL, Bioma VARCHAR(50) NOT NULL, Bloco VARCHAR(50) NOT NULL, PRIMARY KEY (Bioma, Bloco), FOREIGN KEY (Bioma) REFERENCES TIPO_BIOMA(Nome), FOREIGN KEY (Bloco) REFERENCES TIPO_BLOCO(Nome));
CREATE TABLE GERAÇÃO_MOB_BIOMA (Taxa_de_Spawn INT NOT NULL, Mob VARCHAR(50) NOT NULL, Bioma VARCHAR(50) NOT NULL, PRIMARY KEY (Mob, Bioma), FOREIGN KEY (Mob) REFERENCES TIPO_MOB(Nome), FOREIGN KEY (Bioma) REFERENCES TIPO_BIOMA(Nome));
